export default {
    data() {
        return {
            currentRotation: 0,
            isSpinning: false,
            currentChoice: '',
            currentQuestion: '',
            dialog: false
        };
    },
    methods: {
        rotateBottle() {
            if (this.isSpinning) return;

            this.isSpinning = true;
            this.currentChoice = '';
            this.currentQuestion = '';
            this.dialog = false;

            const bottleEl = this.$refs.bottle.$el;
            const extraSpin = Math.floor(Math.random() * 720 + 720);
            this.currentRotation += extraSpin;

            bottleEl.style.transition = "transform 3s ease-out";
            bottleEl.style.transform = `rotate(${this.currentRotation}deg)`;

            setTimeout(() => {
                this.isSpinning = false;
                this.dialog = true; // Show choice popup
            }, 3000);
        },
        choose(type) {
            this.currentChoice = type;
            const list = questions[type];
            const randomIndex = Math.floor(Math.random() * list.length);
            this.currentQuestion = list[randomIndex];
        },
        rotateAgain() {
            this.dialog = false;
            this.rotateBottle();
        }
    }
};
